function _verifyScopeDiagnostic(StreamFinalityScope memory scope)
        private
        view
        returns (bool currentRouteMatches, bytes32 finalityRecordHash, bytes32 componentsHash)
    {
        (
            bool finalized,
            bytes32 recHash,
            bytes32 compHash,
            StreamFinalityComponentExpectation[] storage stored
